func fetch(ctx context.Context, url string) (string, error) {
    ch := make(chan string) // unbuffered: the sender needs a receiver
    go func() { ch <- httpGet(url) }()

    select {
    case v := <-ch:
        return v, nil
    case <-ctx.Done():
        return "", ctx.Err() // nobody will ever read ch: the goroutine leaks
    }
}

func merge(a, b <-chan int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for a != nil || b != nil {
            select {
            case v, ok := <-a:
                if !ok {
                    a = nil // disable this case, stop spinning on a closed channel
                    continue
                }
                out <- v
            case v, ok := <-b:
                if !ok {
                    b = nil
                    continue
                }
                out <- v
            }
        }
    }()
    return out
}

func gen(ctx context.Context, nums ...int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for _, n := range nums {
            select {
            case out <- n:
            case <-ctx.Done(): // downstream gave up: exit instead of blocking
                return
            }
        }
    }()
    return out
}

